package net.officefloor.hq.app.period;

import java.time.LocalDate;
import java.util.List;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.role.RoleService;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

/**
 * The sheet's periods: added on the screen, each a name unique on the sheet (without regard to
 * case) and a from and to date, both inclusive; no two periods on a sheet overlap. A period can be
 * closed once: closing fixes its due-total at that moment, and no claim dated inside a closed
 * period can be added, edited, opened, settled or voided. A steward can reopen a closed period, which
 * makes its due-total live again. With grace days set, a change of the sheet's today closes the
 * periods past them (see {@link SheetService#setToday}).
 */
@Service
public class PeriodService {

    private final PeriodRepository periods;
    private final SheetService sheets;
    private final SheetRepository sheetRows;
    private final Audit audit;
    private final RoleService roles;

    public PeriodService(PeriodRepository periods, SheetService sheets, SheetRepository sheetRows, Audit audit,
            RoleService roles) {
        this.roles = roles;
        this.periods = periods;
        this.sheets = sheets;
        this.sheetRows = sheetRows;
        this.audit = audit;
    }

    @Transactional(readOnly = true)
    public List<Period> list(String sheetId) {
        return periods.findBySheetIdOrderByFromDateAsc(sheetId);
    }

    @Transactional
    public Period add(String sheetId, String user, String name, LocalDate from, LocalDate to) {
        roles.refuseViewer(sheetId, user);
        if (to.isBefore(from)) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "A period's to-date cannot be before its from-date.");
        }
        sheets.load(sheetId, user);
        // hold the sheet so two periods added at the same moment are checked one after the other
        sheetRows.findLockedById(sheetId);
        if (periods.existsBySheetIdAndNameIgnoreCase(sheetId, name)) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "That period name is already in use on this sheet.");
        }
        if (periods.existsBySheetIdAndFromDateLessThanEqualAndToDateGreaterThanEqual(sheetId, to, from)) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "That period overlaps another.");
        }
        Period added;
        try {
            added = periods.saveAndFlush(new Period(sheetId, name, from, to));
        } catch (DataIntegrityViolationException e) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "That period name is already in use on this sheet.");
        }
        audit.recordOnCommit("PERIOD_ADDED sheet=" + sheetId + " by=" + user + " period=" + added.getName() + " from="
                + added.getFromDate() + " to=" + added.getToDate());
        return added;
    }

    /** Close a period, fixing its due-total now; refused (403) for a role the permission matrix does not allow and (409) when it is already closed. */
    @Transactional
    public Period close(String sheetId, String user, long id) {
        roles.refuseUnlessPermitted(sheetId, user, "close");
        // hold the sheet so no claim changes while the period's due-total is fixed
        sheetRows.findLockedById(sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such sheet."));
        Period period = periods.findByIdAndSheetId(id, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such period on this sheet."));
        if (period.isClosed()) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "That period is already closed.");
        }
        return sheets.closePeriod(sheetId, user, period, false);
    }

    /**
     * Reopen a closed period, making its due-total live again; refused (403) for a role the
     * permission matrix does not allow and (409) when the period is not closed.
     */
    @Transactional
    public Period reopen(String sheetId, String user, long id) {
        sheetRows.findLockedById(sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such sheet."));
        Period period = periods.findByIdAndSheetId(id, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such period on this sheet."));
        roles.refuseUnlessPermitted(sheetId, user, "reopen");
        if (!period.isClosed()) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "That period is not closed.");
        }
        period.reopen();
        Period saved = periods.saveAndFlush(period);
        audit.recordOnCommit("PERIOD_REOPENED sheet=" + sheetId + " by=" + user + " period=" + saved.getName());
        return saved;
    }

    /**
     * Refuse (423) a change to a claim dated inside a closed period. Holds the sheet first, so a
     * period cannot close while the change is under way.
     */
    public void refuseIfClosed(String sheetId, LocalDate date) {
        if (isClosed(sheetId, date)) {
            throw new ResponseStatusException(HttpStatus.LOCKED, "That claim's date is inside a closed period.");
        }
    }

    /**
     * Whether a claim dated on this day lies inside a closed period. Holds the sheet first, so a
     * period cannot close while a change that relies on the answer is under way.
     */
    public boolean isClosed(String sheetId, LocalDate date) {
        sheetRows.findLockedById(sheetId);
        return periods.existsBySheetIdAndClosedTrueAndFromDateLessThanEqualAndToDateGreaterThanEqual(sheetId, date,
                date);
    }
}
import { HttpClient, HttpErrorResponse } from '@angular/common/http';
import { Component, effect, inject, input, model, signal } from '@angular/core';
import { firstValueFrom } from 'rxjs';
import { Session } from '../../core/session';
import { money } from '../claims/claims';

// The sheet's periods, by from-date, and the form that adds one: a name unique on the sheet and a
// from and to date, both inclusive, no two periods overlapping. A claim belongs to the period whose
// dates contain its date, or to none; each period shows the due of the claims that count in it.
// A period can be closed: its due-total is then the one fixed when it was closed, and no claim
// dated inside it can be added, edited, opened, settled or voided. Who may close or reopen a period
// is the sheet's permission matrix (see the settings); by default a steward can reopen a closed
// period, making its due-total live again. Each person's row shows their own due-total for every
// period, fixed the same way while it is closed; a period's due-total is the sum of these.
// An open period counts a claim by the status it had at the end of its to-date, as the claim's status
// log records it (a claim with no status by then does not count), at its figure as shown now.
export interface Period {
  id: number;
  name: string;
  from: string;
  to: string;
  closed: boolean;
  /** The due-total fixed when the period was closed; null while it is open. */
  closedDue: string | null;
  /** Each person's due-total for the period fixed when it was closed, by person id; null while open. */
  closedDues: Record<string, string> | null;
}

/** A claim's person, date and its figure in whole cents, for a claim that has one. */
export interface DatedDue {
  personId: number;
  date: string;
  cents: number;
  /** Whether the claim counts by the status it had at the end of a day (yyyy-mm-dd). */
  countsAt: (day: string) => boolean;
}

/** Whether a claim's due falls in an open period: dated inside it, counting at the end of its to-date. */
function inPeriod(p: Period, d: DatedDue): boolean {
  return p.from <= d.date && d.date <= p.to && d.countsAt(p.to);
}

/** A date as the date input gives it: yyyy-mm-dd. */
const DATE = /^\d{4}-\d{2}-\d{2}$/;

/** The period whose dates contain a date (yyyy-mm-dd), if any. */
export function periodOn(periods: readonly Period[], date: string): Period | undefined {
  return periods.find((p) => p.from <= date && date <= p.to);
}

/** A closed period's due-total fixed when it was closed; an open period's, the due of the claims
 *  whose date falls in it that counted at the end of its to-date. */
export function periodDueTotal(p: Period, dues: readonly DatedDue[]): string {
  if (p.closed && p.closedDue !== null) return p.closedDue;
  return money(dues.reduce((sum, d) => sum + (inPeriod(p, d) ? d.cents : 0), 0));
}

/** A person's due-total for a period: for a closed period, the one fixed when it was closed (0.00
 *  for a person added since); for an open one, the due of their claims that counted in it at its end. */
export function personPeriodDueTotal(p: Period, personId: number, dues: readonly DatedDue[]): string {
  if (p.closed && p.closedDues !== null) return p.closedDues[String(personId)] ?? '0.00';
  return money(
    dues.reduce((sum, d) => sum + (d.personId === personId && inPeriod(p, d) ? d.cents : 0), 0),
  );
}

/** Whether a date (yyyy-mm-dd) falls inside a closed period. */
export function inClosedPeriod(periods: readonly Period[], date: string): boolean {
  return periodOn(periods, date)?.closed ?? false;
}

